'use strict';
const $=id=>document.getElementById(id);
const modes={wood:{title:'一声木鱼，万念归寂。',intro:'放下纷扰，让心随着每一次敲击，慢慢安静。',hint:'轻触木鱼，或按 <kbd>空格</kbd> 敲击',label:'本次敲击',auto:'自动敲击',aria:'敲一下木鱼'},beads:{title:'一珠一念，心归当下。',intro:'指尖轻拨，念念相续。不赶路，只观照这一刻。',hint:'左右拖动念珠，或按 <kbd>空格</kbd> 拨动',label:'已拨念珠',auto:'自动拨珠',aria:'拨动一颗念珠'},wheel:{title:'法轮常转，心境澄明。',intro:'轻轻转动，将一份安宁留给自己，也送给众生。',hint:'左右拖动法轮，或按 <kbd>空格</kbd> 转动',label:'转动圈数',auto:'自动转动',aria:'转动法轮'},breath:{title:'一呼一吸，安住于心。',intro:'不必改变什么，只让呼吸带你回到这里。',hint:'点击圆环或按 <kbd>空格</kbd> 开始 / 暂停',label:'呼吸轮次',auto:'开始呼吸',aria:'开始或暂停呼吸冥想'}};
let mode='wood',counts={wood:0,beads:0,wheel:0,breath:0},elapsed=0,started=false,auto=false,autoTimer=null,sound=true,volume=.65,ctx=null,ambience=null,angle=0,targetAngle=0,velocity=0,breathTime=0,lastFrame=0,drag=null,moved=false,reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const canvas=$('canvas'),g=canvas.getContext('2d');
function message(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(message.timer);message.timer=setTimeout(()=>$('toast').classList.remove('show'),2300)}
function audio(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();if(ctx.state==='suspended')ctx.resume();return ctx}
function tone(kind=mode){if(!sound||!volume)return;try{const a=audio(),t=a.currentTime;const notes=kind==='wood'?[480,795,1210]:kind==='beads'?[760,1400]:[220,440,659];notes.forEach((f,i)=>{const o=a.createOscillator(),v=a.createGain();o.type='sine';o.frequency.setValueAtTime(f,t);o.frequency.exponentialRampToValueAtTime(f*.86,t+.13);v.gain.setValueAtTime(.0001,t);v.gain.exponentialRampToValueAtTime(volume*(kind==='wood'?.3:.12)/(i+1),t+.004);v.gain.exponentialRampToValueAtTime(.0001,t+(kind==='wheel'?2.8:.23)+i*.04);o.connect(v).connect(a.destination);o.start(t);o.stop(t+3)});}catch{message('当前浏览器暂不支持音频')}}
function update(){ $('count').innerHTML=counts[mode]+'<small>'+(mode==='wheel'?'圈':mode==='beads'?'颗':mode==='breath'?'轮':'次')+'</small>'; }
function touchFeedback(){if(navigator.vibrate)navigator.vibrate(12);if(reduce)return;$('instrument').classList.remove('strike');void $('instrument').offsetWidth;$('instrument').classList.add('strike');const p=document.createElement('span');p.className='particle';p.textContent=mode==='wood'?'一念清净':mode==='beads'?'念念相续':'心随轮转';p.style.left=(46+Math.random()*8)+'%';$('particles').append(p);setTimeout(()=>p.remove(),1600)}
function act(){started=true;if(mode==='breath'){setAuto(!auto);return}if(mode==='wheel'){velocity+=2.4;tone();touchFeedback();return}counts[mode]++;if(mode==='beads')targetAngle+=Math.PI*2/18;tone();touchFeedback();update()}
function setAuto(on){clearInterval(autoTimer);autoTimer=null;auto=on;$('auto').setAttribute('aria-pressed',String(auto));$('play-icon').textContent=auto?'Ⅱ':'▷';$('auto-text').textContent=auto?'暂停修行':modes[mode].auto;if(mode==='breath'){document.querySelector('.breath-circle').style.animationPlayState=auto?'running':'paused';if(auto){started=true;audio()}}else if(auto){started=true;audio();autoTimer=setInterval(act,60000/Number($('tempo').value))}}
function selectMode(next){if(!modes[next])throw new Error('未知修行方式');setAuto(false);mode=next;if(mode==='breath'){breathTime=0;document.getElementById("breath-label").textContent='吸气';const circle=document.querySelector('.breath-circle');circle.style.animation='none';void circle.offsetWidth;circle.style.animation='';circle.style.animationPlayState='paused'}velocity=0;angle=0;targetAngle=0;const m=modes[mode];$('heading').textContent=m.title;$('intro').textContent=m.intro;$('hint').innerHTML=m.hint;$('count-label').textContent=m.label;$('auto-text').textContent=m.auto;$('instrument').setAttribute('aria-label',m.aria);$('wood-image').hidden=mode!=='wood';$('canvas').hidden=!['beads','wheel'].includes(mode);$('breathing').hidden=mode!=='breath';$('wood-fallback').hidden=true;$('tempo-label').hidden=mode==='breath';$('mantra').textContent=mode==='breath'?'吸气 4 秒 · 停留 2 秒 · 呼气 4 秒 · 停留 2 秒':'南 无 阿 弥 陀 佛';document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});update();draw()}
function draw(){g.clearRect(0,0,900,720);g.save();g.translate(450,365);if(mode==='beads'){g.rotate(angle);g.strokeStyle='#94744b';g.lineWidth=3;g.beginPath();g.ellipse(0,0,213,213,0,0,Math.PI*2);g.stroke();for(let i=0;i<18;i++){const a=i/18*Math.PI*2,x=Math.cos(a)*213,y=Math.sin(a)*213;g.shadowColor='#000';g.shadowBlur=18;g.shadowOffsetY=9;const grad=g.createRadialGradient(x-10,y-12,2,x,y,34);grad.addColorStop(0,i===0?'#dcbd78':'#a97947');grad.addColorStop(.3,i===0?'#b79759':'#765132');grad.addColorStop(1,'#241b13');g.fillStyle=grad;g.beginPath();g.arc(x,y,i===0?37:32,0,Math.PI*2);g.fill();g.shadowBlur=0;g.shadowOffsetY=0;g.strokeStyle='#c9a26a22';g.lineWidth=1;g.stroke()}g.rotate(-angle);g.fillStyle='#b8a376';g.font='25px serif';g.textAlign='center';g.fillText('念 念 相 续',0,10)}else if(mode==='wheel'){g.rotate(angle);g.shadowColor='#ae834330';g.shadowBlur=28;[215,195,163,58].forEach((r,i)=>{g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.strokeStyle=['#c2a068','#71603c','#a98850','#d1b77c'][i];g.lineWidth=i===0?12:4;g.stroke()});for(let i=0;i<8;i++){g.save();g.rotate(i*Math.PI/4);let grad=g.createLinearGradient(-10,0,10,0);grad.addColorStop(0,'#665335');grad.addColorStop(.5,'#d2b576');grad.addColorStop(1,'#81643c');g.fillStyle=grad;g.beginPath();g.moveTo(-8,-58);g.lineTo(-14,-164);g.lineTo(0,-187);g.lineTo(14,-164);g.lineTo(8,-58);g.closePath();g.fill();g.beginPath();g.arc(0,-216,8,0,Math.PI*2);g.fill();g.restore()}const grad=g.createRadialGradient(-10,-10,0,0,0,42);grad.addColorStop(0,'#cfb783');grad.addColorStop(1,'#6b5330');g.fillStyle=grad;g.beginPath();g.arc(0,0,42,0,Math.PI*2);g.fill()}g.restore()}
function frame(time){const dt=lastFrame?Math.min((time-lastFrame)/1000,.08):0;lastFrame=time;if(mode==='beads'){angle+=(targetAngle-angle)*Math.min(1,dt*10);draw()}if(mode==='wheel'){const prev=Math.floor(angle/(Math.PI*2));angle+=velocity*dt;velocity*=Math.pow(.75,dt);if(Math.abs(velocity)<.006)velocity=0;const next=Math.floor(angle/(Math.PI*2));if(next>prev){counts.wheel+=next-prev;update()}draw()}if(mode==='breath'&&auto){const prev=Math.floor(breathTime/12);breathTime+=dt;if(Math.floor(breathTime/12)>prev){counts.breath++;update();tone('wheel')}const t=breathTime%12;$('breath-label').textContent=t<4?'吸气':t<6?'停留':t<10?'呼气':'停留'}requestAnimationFrame(frame)}
function setAmbient(kind){if(ambience){ambience.source.stop();ambience=null}document.querySelectorAll('[data-ambient]').forEach(b=>{b.classList.toggle('active',b.dataset.ambient===kind);b.setAttribute('aria-pressed',String(b.dataset.ambient===kind))});if(kind==='none')return;try{const a=audio(),buf=a.createBuffer(1,a.sampleRate*4,a.sampleRate),data=buf.getChannelData(0);let brown=0;for(let i=0;i<data.length;i++){let white=Math.random()*2-1;brown=(brown+.02*white)/1.02;data[i]=kind==='rain'?white*.3:kind==='wind'?brown*4:(brown*3+white*.06)*(0.7+Math.sin(i/a.sampleRate*7)*.15)}const source=a.createBufferSource(),filter=a.createBiquadFilter(),gain=a.createGain();source.buffer=buf;source.loop=true;filter.type='lowpass';filter.frequency.value=kind==='rain'?2600:kind==='wind'?550:1400;gain.gain.value=volume*.5;source.connect(filter).connect(gain).connect(a.destination);source.start();ambience={source,gain}}catch{message('声景无法播放，请重新尝试')}}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>selectMode(b.dataset.mode));document.querySelectorAll('[data-ambient]').forEach(b=>b.onclick=()=>setAmbient(b.dataset.ambient));
$('instrument').onclick=()=>{if(!moved)act();moved=false};$('instrument').onpointerdown=e=>{moved=false;if(!['beads','wheel'].includes(mode))return;drag={x:e.clientX,last:e.clientX,total:0};$('instrument').setPointerCapture(e.pointerId)};$('instrument').onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.last;drag.last=e.clientX;drag.total+=Math.abs(dx);if(drag.total<8)return;moved=true;started=true;if(mode==='wheel'){velocity=Math.min(18,Math.max(0,velocity+Math.abs(dx)*.025))}else{targetAngle+=Math.abs(dx)*.008;if(Math.abs(e.clientX-drag.x)>25){counts.beads++;drag.x=e.clientX;tone();update()}}};$('instrument').onpointerup=()=>{drag=null};$('instrument').onpointercancel=()=>{drag=null;moved=false};
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','BUTTON','SELECT','TEXTAREA'].includes(e.target.tagName)){e.preventDefault();if(!e.repeat)act()}if(e.key==='Escape'&&document.body.classList.contains('immersed'))toggleImmersion(false)});
$('auto').onclick=()=>setAuto(!auto);$('tempo').oninput=()=>{$('tempo-value').textContent=$('tempo').value;if(auto)setAuto(true)};$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').innerHTML='♫ <span>音效'+(sound?'开启':'关闭')+'</span>';if(sound)tone()};$('volume').oninput=()=>{volume=Number($('volume').value)/100;if(ambience)ambience.gain.gain.setTargetAtTime(volume*.5,ctx.currentTime,.1)};
$('reset').onclick=()=>{setAuto(false);counts={wood:0,beads:0,wheel:0,breath:0};elapsed=0;started=false;breathTime=0;velocity=angle=targetAngle=0;$('timer').innerHTML='00<em>:</em>00';$('breath-label').textContent='吸气';const c=document.querySelector('.breath-circle');c.style.animation='none';void c.offsetWidth;c.style.animation='';c.style.animationPlayState='paused';update();draw();message('新的一念，从此刻开始')};
function toggleImmersion(force){const on=force===undefined?!document.body.classList.contains('immersed'):force;document.body.classList.toggle('immersed',on);$('immersive').innerHTML=on?'⛶ <span>退出沉浸 · Esc</span>':'⛶ <span>沉浸模式</span>';$('immersive').setAttribute('aria-pressed',String(on))}$('immersive').onclick=()=>toggleImmersion();
setInterval(()=>{if(!started||document.hidden)return;elapsed++;$('timer').innerHTML=String(Math.floor(elapsed/60)).padStart(2,'0')+'<em>:</em>'+String(elapsed%60).padStart(2,'0')},1000);document.addEventListener('visibilitychange',()=>{if(document.hidden){setAuto(false);if(ctx)ctx.suspend()}else if(ctx)ctx.resume()});
$('wood-image').src='wood.png';$('wood-image').onload=()=>{$('wood-fallback').hidden=true;if(mode==='wood')$('wood-image').hidden=false};$('wood-image').onerror=()=>{if(mode==='wood'){$('wood-fallback').hidden=false;message('木鱼图像加载失败，仍可点击敲击')}};selectMode('wood');requestAnimationFrame(frame);
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'select_meditation_practice',title:'切换修行方式',description:'切换到木鱼、念珠、法轮或呼吸冥想，并暂停自动修行。',inputSchema:{type:'object',properties:{mode:{type:'string',enum:Object.keys(modes)}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.mode!=='string'||!modes[input.mode])throw new Error('无效的修行方式');selectMode(input.mode);return{mode,count:counts[mode],automatic:auto}}})}catch{}}
